import{_ as e,o as a,c as d,ae as s}from"./chunks/framework.CSxHcPWC.js";const k=JSON.parse('{"title":"Global Master Policies","description":"","frontmatter":{},"headers":[],"relativePath":"dsl-rules.md","filePath":"dsl-rules.md"}'),o={name:"dsl-rules.md"};function i(l,t,r,n,c,h){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="global-master-policies" tabindex="-1">Global Master Policies <a class="header-anchor" href="#global-master-policies" aria-label="Permalink to &quot;Global Master Policies&quot;">​</a></h1><p>Sentinel V2 applies <strong>one policy per account</strong> to every API key under that tenant on <code>POST /v2/evaluate</code>.</p><p>Configure it in the dashboard: <strong>Sentinel V2 Global Master Policies</strong> → <code>GET</code> / <code>POST /api/policy/global</code>.</p><p>There is <strong>no dashboard DSL editor</strong> today. Custom <code>rules</code> strings, ASN allow/block lists, and country lists are not shipped. The engine may retain a parser for future use; it is not a live product surface.</p><hr><h2 id="controls-what-ships" tabindex="-1">Controls (what ships) <a class="header-anchor" href="#controls-what-ships" aria-label="Permalink to &quot;Controls (what ships)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Field</th><th>Effect</th></tr></thead><tbody><tr><td>Engine mode</td><td><code>mode</code></td><td>Score thresholds: <code>PASSIVE</code>, <code>BALANCED</code>, <code>STRICT</code>, <code>DRACONIAN</code>, <code>HUMAN_ONLY</code></td></tr><tr><td>VPN / Proxy</td><td><code>vpn_action</code></td><td><code>allow</code> (score only), <code>challenge</code>, or <code>block</code> when VPN is detected</td></tr><tr><td>Datacenter IPs</td><td><code>datacenter_action</code></td><td>Same for hosting/cloud ranges</td></tr><tr><td>Force BWT</td><td><code>force_bwt</code></td><td>Challenge browsers without a trust token <strong>before</strong> mode math</td></tr><tr><td>Exempt server clients</td><td><code>exempt_server_requests</code></td><td>Skips Force BWT only (not VPN/DC or mode)</td></tr><tr><td>PoW difficulty</td><td><code>difficulty_level</code></td><td><code>1</code>–<code>5</code> for <code>/v1/challenge/issue</code> when a valid tenant key is present</td></tr></tbody></table><h3 id="evaluation-order" tabindex="-1">Evaluation order <a class="header-anchor" href="#evaluation-order" aria-label="Permalink to &quot;Evaluation order&quot;">​</a></h3><ol><li>Private IP → mode math only</li><li>Collect signals (token, VPN cache, ASN matrix, velocity, verified bot / scanner)</li><li><strong>Verified bot</strong> → skip VPN/DC hard blocks and Force BWT; mode still applies</li><li>Valid trust token → skip infrastructure hard blocks; mode still applies</li><li>VPN / datacenter hard actions</li><li>Force BWT (if enabled)</li><li>Score + mode thresholds</li></ol><hr><h2 id="modes-thresholds" tabindex="-1">Modes (thresholds) <a class="header-anchor" href="#modes-thresholds" aria-label="Permalink to &quot;Modes (thresholds)&quot;">​</a></h2><p>Signal weights (sum, clamped ±100):</p><table tabindex="0"><thead><tr><th>Signal</th><th>Weight</th></tr></thead><tbody><tr><td><code>TOKEN_VALID</code></td><td>+30</td></tr><tr><td><code>VERIFIED_BOT</code></td><td>+50</td></tr><tr><td><code>RESIDENTIAL_IP</code></td><td>+10</td></tr><tr><td><code>VPN_DETECTED</code></td><td>−10</td></tr><tr><td><code>DATACENTER_IP</code></td><td>−20</td></tr><tr><td><code>HIGH_VELOCITY</code></td><td>−30</td></tr><tr><td><code>SCANNER_PATTERN</code></td><td>−60</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Mode</th><th>ALLOW</th><th>CHALLENGE</th><th>else</th></tr></thead><tbody><tr><td><code>PASSIVE</code></td><td>score ≥ −20</td><td>score ≥ −40</td><td><code>BLOCK</code></td></tr><tr><td><code>BALANCED</code></td><td>score ≥ 10</td><td>score ≥ −20</td><td><code>BLOCK</code></td></tr><tr><td><code>STRICT</code></td><td>score ≥ 38</td><td>score ≥ −10</td><td><code>BLOCK</code></td></tr><tr><td><code>DRACONIAN</code></td><td>score ≥ 38</td><td>score ≥ 25</td><td><code>BLOCK</code></td></tr><tr><td><code>HUMAN_ONLY</code></td><td>residential + token, or <code>VERIFIED_BOT</code></td><td>token only</td><td><code>BLOCK</code> (scanner/velocity → <code>BLOCK</code>)</td></tr></tbody></table><hr><h2 id="example-policy-payload" tabindex="-1">Example policy payload <a class="header-anchor" href="#example-policy-payload" aria-label="Permalink to &quot;Example policy payload&quot;">​</a></h2><p>What the dashboard saves today:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BALANCED&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;difficulty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;vpn_action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;challenge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;datacenter_action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;block&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;force_bwt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exempt_server_requests&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="verified-bots" tabindex="-1">Verified bots <a class="header-anchor" href="#verified-bots" aria-label="Permalink to &quot;Verified bots&quot;">​</a></h2><p>V2 recognizes known-good crawler User-Agents (Googlebot, Bingbot, Applebot, and similar) and emits <code>VERIFIED_BOT</code> (+50). Those requests are not tagged as <code>SCANNER_PATTERN</code>, and they skip Force BWT / VPN / DC hard blocks. Mode thresholds still apply (<code>HUMAN_ONLY</code> explicitly allows <code>VERIFIED_BOT</code>).</p><hr><h2 id="roadmap-not-available-yet" tabindex="-1">Roadmap (not available yet) <a class="header-anchor" href="#roadmap-not-available-yet" aria-label="Permalink to &quot;Roadmap (not available yet)&quot;">​</a></h2><ul><li>Custom DSL rule strings in the dashboard</li><li>Per-tenant ASN / country allow and block lists</li></ul><p>Until those ship, do not document them as live features.</p>`,25)])])}const E=e(o,[["render",i]]);export{k as __pageData,E as default};
